    private requireDraft(actionId: string) {
        this.getDraft(actionId)
        const draft = this.drafts.get(actionId)
        if (!draft) throw new Error(`Missing action draft: ${actionId}`)

        return draft
    }

    private queueDraftSave(
        actionId: string,
        definition: RawActionDefinition,
        revision: number,
        targetPath: string,
        recreate = false,
    ) {
        const current = this.requireDraft(actionId)
        const deletionRevision = current.deletionRevision
        const sourcePath = current.sourcePath
        const saveReference = this.findOpenDocument(actionId)?.createSaveReference()
        const chain = current.chain.then(async () => {
            const startedDraft = this.drafts.get(actionId)
            if (!startedDraft) return
            if (startedDraft.deletionRevision !== deletionRevision || (startedDraft.deleted && !recreate)) return
            this.drafts.set(actionId, { ...startedDraft, error: null, recreating: recreate, saving: true })
            this.host.dispatchDraftChanged(actionId)
            this.host.dispatchPersistenceChanged()
            try {
                await this.host.saveDefinition(
                    sourcePath,
                    definition,
                    targetPath,
                    saveReference,
                    () => this.acknowledgeDraftPersistence(actionId, revision, deletionRevision),
                )
                const savedDraft = this.drafts.get(actionId)
                if (!savedDraft || savedDraft.deletionRevision !== deletionRevision) return
                this.drafts.set(actionId, {
                    ...savedDraft,
                    deleted: recreate ? false : savedDraft.deleted,
                    error: null,
                    recreating: false,
                    saving: false,
                })
            } catch (error) {
                const failedDraft = this.drafts.get(actionId)
                if (!failedDraft || failedDraft.deletionRevision !== deletionRevision) return
                const message = error instanceof Error ? error.message : 'Action save failed'
                this.drafts.set(actionId, { ...failedDraft, error: message, recreating: false, saving: false })
            }
            this.host.dispatchDraftChanged(actionId)
            this.host.dispatchPersistenceChanged()
        })
        this.drafts.set(actionId, { ...current, chain })
    }

    private acknowledgeDraftPersistence(actionId: string, revision: number, deletionRevision: number) {
        const draft = this.drafts.get(actionId)
        if (!draft || draft.deletionRevision !== deletionRevision) return

        this.drafts.set(actionId, { ...draft, savedRevision: Math.max(draft.savedRevision, revision) })
        this.host.dispatchDraftChanged(actionId)
        this.host.dispatchPersistenceChanged()
    }

    private findOpenDocument(actionId: string): ActionOpenDocument | null {
        const action = this.drafts.get(actionId)?.action ?? this.host.getActionById(actionId)
        if (!action) return null

        const document = openFilesService.findDocument(action)
        return document?.kind === 'action' ? document : null
    }

    private updateOpenDocument(actionId: string, definition: RawActionDefinition) {
        this.findOpenDocument(actionId)?.updateDraft(definition, this.host)
    }
}

import { Alert, Box, Button, Stack, Typography } from '@mui/material'
import { useEffect, useState } from 'react'
import type { ActionDefinition } from '../../../data/action_types'
import {
    ACTION_DRAFT_CHANGED_EVENT,
    actionService,
    type ActionDraftChangedDetail,
} from '../../../services/actions/action_service'
import { dialogService } from '../../../services/dialog_service'
import { openFilesService } from '../../../services/open_files_service'
import { useWorktrees } from '../../hooks/use_worktrees'
import { ActionDefinitionFields } from './action_definition_fields'
import { ACTION_DEFINITION_TAB } from './action_phrase_editor_state'
import { useProjectReadOnly } from '../../hooks/use_project_read_only'

interface ActionEditorContentProps {
    action: ActionDefinition
    cardTypes: string[]
    sourcePath: string
    specialContextTypes: string[]
    states: string[]
}

/** Definition and recovery region backed directly by ActionService. */
export function ActionEditorContent(props: ActionEditorContentProps) {
    const { action, cardTypes, sourcePath, specialContextTypes, states } = props
    const readOnly = useProjectReadOnly()
    const [, setRevision] = useState(0)
    useEffect(() => {
        const handleChanged = (event: Event) => {
            const { actionId } = (event as CustomEvent<ActionDraftChangedDetail>).detail
            if (actionId === action.id) setRevision((current) => current + 1)
        }
        actionService.addEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)

        return () => actionService.removeEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)
    }, [action.id])
    const draft = actionService.draftStore.getDraft(action.id)
    const { conflict, definition, deleted, error: saveError, saving, validation } = draft
    const activeTab = (actionService.getActionById(action.id) ?? action).editorState?.selectedTab ?? ACTION_DEFINITION_TAB
    const openDocument = openFilesService.findDocument(action)
    const canRetry = !!saveError && validation.valid && !!openDocument?.dirty && !conflict && !saving
    const status = saveError ? 'Save failed. Retry to save changes.' : validation.valid ? null : 'Fix validation errors to save.'
    const showActionContent = definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB || !!saveError || deleted || !!conflict
    const worktrees = useWorktrees()

    useEffect(() => {
        if (validation.error) dialogService.error(validation.error, { title: 'Invalid action' })
    }, [validation.error])
    const handleRetry = () => actionService.draftStore.retryDraft(action.id)
    const handleRecreateDeleted = () => actionService.draftStore.recreateDeletedDraft(action.id)
    const handleDiscardDeleted = () => {
        actionService.draftStore.discardDeletedDraft(action.id)
        const document = openFilesService.getSnapshot().documents.find((candidate) => (
            candidate.kind === 'action' && candidate.getObject().id === action.id
        ))
        if (document) openFilesService.closeDocument(document)
    }
    const handleKeepMine = () => actionService.draftStore.keepDraft(action.id)
    const handleReloadExternal = () => actionService.draftStore.reloadDraft(action.id)

    return (
        <Box
            component="fieldset"
            data-testid="action-editor-content"
            disabled={readOnly}
            hidden={!showActionContent}
            sx={{ border: 0, flex: activeTab === ACTION_DEFINITION_TAB || definition.type !== 'agent' ? 1 : '0 0 auto', m: 0, minHeight: 0, order: 1, overflowY: 'auto', p: 2 }}
        >
            {saveError ? (
                <Alert action={<Button color="inherit" disabled={!canRetry} onClick={handleRetry} size="small">Retry save</Button>} severity="error" sx={{ mb: 2 }}>
                    {saveError}
                </Alert>
            ) : null}
            {deleted ? (
                <Alert
                    action={(
                        <Stack direction="row" spacing={1}>
                            <Button color="inherit" disabled={!validation.valid || saving} onClick={handleRecreateDeleted} size="small">Recreate file</Button>
                            <Button color="inherit" onClick={handleDiscardDeleted} size="small">Discard draft</Button>
                        </Stack>
                    )}
                    severity="warning"
                    sx={{ mb: 2 }}
                >
                    This action file was deleted outside the editor. Recreate it or discard this draft.
                </Alert>
            ) : null}
            {conflict ? (
                <Alert
                    action={(
                        <Stack direction="row" spacing={1}>
                            <Button color="inherit" onClick={handleKeepMine} size="small">Keep my changes</Button>
                            <Button color="inherit" onClick={handleReloadExternal} size="small">Reload from disk</Button>
                        </Stack>
                    )}
                    severity="warning"
                    sx={{ mb: 2 }}
                >
                    This action was changed outside the editor while you had unsaved edits.
                </Alert>
            ) : null}
            {(definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB) ? (
                <ActionDefinitionFields
                    actionId={action.id}
                    actions={actionService.getActions()}
                    cardTypes={cardTypes}
                    sourcePath={sourcePath}
                    specialContextTypes={specialContextTypes}
                    states={states}
                    worktrees={worktrees}
                />
            ) : null}
            {status && (definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB) ? (
                <Typography color={validation.valid ? 'text.secondary' : 'error'} sx={{ mt: 1 }} variant="caption">{status}</Typography>
            ) : null}
        </Box>
    )
}

import {
    type ActionDefinition,
    type ActionFile,
    type RawActionDefinition,
} from '../../data/action_types'
import { ActionValidationError } from '../../../../shared/action_definitions.mjs'
import { validateActionDefinition } from './action_definition_loader'
import type { ActionValidationResult } from './action_service'

export const ACTION_FILE_EXTENSION = '.json'
export const NEW_ACTION_NAME = 'new-action'

export function normalizedPathKey(path: string) {
    return path.replace(/\\/gu, '/').toLowerCase()
}

export function normalizedFolder(folder: string) {
    return folder.replace(/\\/gu, '/').replace(/\/+$/u, '')
}

export function actionPath(folder: string, name: string) {
    return `${normalizedFolder(folder)}/${name}${ACTION_FILE_EXTENSION}`
}

export function nextActionName(files: ActionFile[]) {
    const existingPaths = new Set(files.map(({ path }) => normalizedPathKey(path)))
    if (![...existingPaths].some((path) => path.endsWith(`/${NEW_ACTION_NAME}${ACTION_FILE_EXTENSION}`))) return NEW_ACTION_NAME

    let suffix = 2
    while ([...existingPaths].some((path) => path.endsWith(`/${NEW_ACTION_NAME}-${suffix}${ACTION_FILE_EXTENSION}`))) suffix += 1

    return `${NEW_ACTION_NAME}-${suffix}`
}

export function suffixedActionPath(path: string, suffix: number) {
    return `${path.slice(0, -ACTION_FILE_EXTENSION.length)}-${suffix}${ACTION_FILE_EXTENSION}`
}

export function preserveActionEditorStates(currentActions: ActionDefinition[], nextActions: ActionDefinition[]) {
    const editorStatesByActionId = new Map<string, NonNullable<ActionDefinition['editorState']>>()
    for (const { editorState, id } of currentActions) {
        if (!editorState) continue
        editorStatesByActionId.set(id, editorState)
    }
    for (const action of nextActions) {
        const editorState = editorStatesByActionId.get(action.id)
        if (editorState) action.editorState = editorState
    }

    return nextActions
}

export function structuredValuesEqual(left: unknown, right: unknown): boolean {
    if (left === right) return true
    if (Array.isArray(left) || Array.isArray(right)) {
        if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false

        return left.every((value, index) => structuredValuesEqual(value, right[index]))
    }
    if (left === null || right === null || typeof left !== 'object' || typeof right !== 'object') return false

    const leftRecord = left as Record<string, unknown>
    const rightRecord = right as Record<string, unknown>
    const leftKeys = Object.keys(leftRecord).filter((key) => leftRecord[key] !== undefined)
    const rightKeys = Object.keys(rightRecord).filter((key) => rightRecord[key] !== undefined)
    if (leftKeys.length !== rightKeys.length) return false

    return leftKeys.every((key) => Object.hasOwn(rightRecord, key)
        && rightRecord[key] !== undefined
        && structuredValuesEqual(leftRecord[key], rightRecord[key]))
}

export function actionDefinitionsEqual(left: RawActionDefinition, right: RawActionDefinition) {
    return structuredValuesEqual(left, right)
}

export function actionValidationResult(validate: () => unknown): ActionValidationResult {
    try {
        validate()

        return { code: null, error: null, field: null, fieldPath: null, index: null, valid: true }
    } catch (error) {
        if (error instanceof ActionValidationError) {
            return {
                code: error.code,
                error: error.message,
                field: error.field as keyof RawActionDefinition | null,
                fieldPath: error.fieldPath,
                index: error.index,
                valid: false,
            }
        }
        const message = error instanceof Error ? error.message : 'Invalid action definition'

        return { code: null, error: message, field: null, fieldPath: null, index: null, valid: false }
    }
}

export function validateDraftDefinition(path: string, definition: RawActionDefinition) {
    return actionValidationResult(() => validateActionDefinition(definition, path))
}

/** Convert a loaded action back to its canonical editable JSON shape. */
export function editableActionDefinition(action: ActionDefinition): RawActionDefinition {
    if (action.builtin) throw new Error(`Built-in action cannot be edited: ${action.id}`)

    return {
        id: action.id,
        label: action.label,
        description: action.description,
        type: action.type,
        ...(action.icon !== null ? { icon: action.icon } : {}),
        ...(action.appliesTo !== null ? { appliesTo: action.appliesTo } : {}),
        ...(action.autoFinish != null ? { autoFinish: action.autoFinish } : {}),
        ...(action.onBefore.length > 0 ? { onBefore: action.onBefore.map(({ id }) => id) } : {}),
        ...(action.on.length > 0 ? { on: action.on.map(({ actionId, condition }) => ({ actionId, condition })) } : {}),
        ...(action.onAfter.length > 0 ? { onAfter: action.onAfter.map(({ id }) => id) } : {}),
        ...(action.onState !== null ? { onState: action.onState } : {}),
        ...(action.output !== null ? { output: action.output } : {}),
        ...(action.needsWorkTree ? { needsWorkTree: true } : {}),
        ...(action.showCommandWindow ? { showCommandWindow: true } : {}),
        ...(action.agent !== null ? { agent: action.agent } : {}),
        ...(action.model !== null ? { model: action.model } : {}),
        ...(action.permissionMode !== null ? { permissionMode: action.permissionMode } : {}),
        ...(action.thinkingLevel !== null ? { thinkingLevel: action.thinkingLevel } : {}),
        ...(action.trackFileChanges ? { trackFileChanges: true } : {}),
        ...(action.streaming ? { streaming: true } : {}),
        ...(action.userInput != null ? { userInput: action.userInput } : {}),
        phrases: action.phrases,
        ...(action.type === 'agent' ? { prompt: action.prompt as string } : { command: action.command as string }),
    }
}

