function shouldReserveConversation(action: ActionDefinition, context: ActionContext, input: ActionRunInput) {
    return action.type === 'agent'
        && !input.continueFrom
        && (context.kind === 'card' || context.kind === 'file')
        && !!context.cardInternalId
